package txsaga

import (
	"context"
	"strings"
	"sync"
	"time"
)

// ValidateDefinition 校验 Saga 定义，非法时返回 ErrInvalidDefinition（可 errors.Is）。
// 规则：名称非空、至少一个步骤、每个步骤名非空且不重复、每个步骤都提供正向动作。
func ValidateDefinition(d Definition) error {
	if strings.TrimSpace(d.Name) == "" {
		return ErrInvalidDefinition
	}
	if len(d.Steps) == 0 {
		return ErrInvalidDefinition
	}
	seen := make(map[string]struct{}, len(d.Steps))
	for _, st := range d.Steps {
		if strings.TrimSpace(st.Name) == "" || st.Action == nil {
			return ErrInvalidDefinition
		}
		if _, dup := seen[st.Name]; dup {
			return ErrInvalidDefinition
		}
		seen[st.Name] = struct{}{}
	}
	return nil
}

// Engine 在给定 Store 上执行 Saga。零值不可用，请用 NewEngine 创建。
type Engine struct {
	store Store

	// 同执行身份的进程内串行化，避免并发调用重复进入同一未确认动作。
	locksMu sync.Mutex
	locks   map[string]*sync.Mutex

	// now 为可注入时钟；生产使用 time.Now。
	now func() time.Time
}

// NewEngine 创建基于 store 的编排引擎。
func NewEngine(store Store) *Engine {
	return &Engine{store: store, locks: make(map[string]*sync.Mutex), now: time.Now}
}

func (e *Engine) identityLock(businessKey, idempotencyKey string) *sync.Mutex {
	key := businessKey + "\x00" + idempotencyKey
	e.locksMu.Lock()
	m, ok := e.locks[key]
	if !ok {
		m = &sync.Mutex{}
		e.locks[key] = m
	}
	e.locksMu.Unlock()
	return m
}

type execView struct {
	state   *ExecutionState
	payload any
}

func (v execView) BusinessKey() string    { return v.state.BusinessKey }
func (v execView) SagaName() string       { return v.state.SagaName }
func (v execView) IdempotencyKey() string { return v.state.IdempotencyKey }
func (v execView) Payload() any           { return v.payload }

func (v execView) SucceededSteps() []string {
	var names []string
	for _, st := range v.state.Steps {
		if st.Status == StepResultSucceeded {
			names = append(names, st.Name)
		}
	}
	return names
}

// Execute 按 Definition 执行一次 Saga 请求。
//
// 执行身份由业务键、Saga 定义与外部幂等键共同确定：
//   - 新身份：创建执行并顺序执行未完成步骤；
//   - 同身份重试：不重复执行已确认成功的正向步骤或补偿步骤；
//     结果未确认的步骤允许被重新调用，重入次数累计在对应步骤的 Attempts，
//     动作自身须遵守幂等契约；
//   - 已到达终态：直接返回固定的终态结果，不再调用任何动作，也不再追加事件；
//   - 同业务键绑定不同定义：返回 ErrDefinitionConflict；
//   - 非法定义或缺失业务键/幂等键：返回 ErrInvalidDefinition。
//
// 每一步确认后，状态与对应 Outbox 事件在同一个 Store 事务中原子提交，
// 然后才执行下一步。正向动作失败即停止推进，仅逆序补偿此前确认成功的步骤；
// 任一补偿报错则固定为 compensation_failed 终态。
func (e *Engine) Execute(ctx context.Context, def Definition, req ExecutionRequest) (Result, error) {
	if err := ValidateDefinition(def); err != nil {
		return Result{}, err
	}
	if strings.TrimSpace(req.BusinessKey) == "" || strings.TrimSpace(req.IdempotencyKey) == "" {
		return Result{}, ErrInvalidDefinition
	}
	fp := fingerprint(def)

	mu := e.identityLock(req.BusinessKey, req.IdempotencyKey)
	mu.Lock()
	defer mu.Unlock()

	for {
		if err := ctx.Err(); err != nil {
			return Result{}, err
		}
		snap, err := e.store.LoadSnapshot(ctx, req.BusinessKey, req.IdempotencyKey)
		if err != nil {
			return Result{}, err
		}
		if snap.Bound && snap.Binding.Fingerprint != fp {
			return Result{}, ErrDefinitionConflict
		}
		st := snap.State
		if st == nil {
			if err := e.createExecution(ctx, def, fp, req); err != nil {
				return Result{}, err
			}
			continue
		}
		if st.Fingerprint != fp {
			return Result{}, ErrDefinitionConflict
		}
		if st.Terminal() {
			return toResult(st), nil
		}

		switch st.Status {
		case StatusRunning:
			advanced, err := e.advanceForward(ctx, def, req, st)
			if err != nil {
				return Result{}, err
			}
			if !advanced {
				// 所有步骤均已确认成功，重新读取以取得 completed 终态。
				snap2, err := e.store.LoadSnapshot(ctx, req.BusinessKey, req.IdempotencyKey)
				if err != nil {
					return Result{}, err
				}
				return toResult(snap2.State), nil
			}
		case StatusCompensating:
			done, err := e.advanceCompensation(ctx, def, req, st)
			if err != nil {
				return Result{}, err
			}
			if done {
				return e.finishFailed(ctx, req)
			}
		default:
			return Result{}, ErrInvalidDefinition
		}
	}
}

// createExecution 在一个原子事务中建立执行状态并追加 started 事件。
func (e *Engine) createExecution(ctx context.Context, def Definition, fp string, req ExecutionRequest) error {
	return e.store.Commit(ctx, req.BusinessKey, req.IdempotencyKey, func(tx Tx) error {
		if b, ok := tx.Binding(); ok && b.Fingerprint != fp {
			return ErrDefinitionConflict
		}
		if tx.State() != nil {
			return nil // 并发情况下已由其它调用建立，直接沿用
		}
		steps := make([]StepState, len(def.Steps))
		for i, s := range def.Steps {
			steps[i] = StepState{Name: s.Name}
		}
		tx.Create(&ExecutionState{
			SagaName:    def.Name,
			Fingerprint: fp,
			Status:      StatusRunning,
			Steps:       steps,
			Payload:     req.Payload,
		})
		tx.AppendEvent(EventExecutionStarted, EventPayload{
			SagaName:       def.Name,
			IdempotencyKey: req.IdempotencyKey,
			Status:         StatusRunning,
		})
		return nil
	})
}

// advanceForward 执行下一个未完成的正向步骤，在事务外调用动作，再把
// 成功/失败结果与事件原子提交。返回 false 表示已无待执行步骤。
func (e *Engine) advanceForward(ctx context.Context, def Definition, req ExecutionRequest, st *ExecutionState) (bool, error) {
	idx := -1
	for i := range st.Steps {
		if st.Steps[i].Status == "" {
			idx = i
			break
		}
	}
	if idx < 0 {
		return false, nil
	}
	step := def.Steps[idx]

	// Attempts 记录该步骤动作的实际调用次数；同身份重试已确认步骤时不会自增。
	// 未确认结果的步骤被重新调用时该值增大，调用方据此判断是否发生重复处理。
	st.Steps[idx].Attempts++
	st.Steps[idx].StartedAt = e.now()
	if err := ctx.Err(); err != nil {
		return false, err
	}
	actionErr := step.Action(ctx, execView{state: st, payload: req.Payload})
	if err := ctx.Err(); err != nil {
		// 调用方取消：不把取消解释为业务失败，未确认的步骤留待后续同身份重试。
		return false, err
	}
	finishedAt := e.now()

	err := e.store.Commit(ctx, req.BusinessKey, req.IdempotencyKey, func(tx Tx) error {
		cur := tx.State()
		if cur == nil || cur.Terminal() {
			return nil // 状态已被其它路径推进，本次结果丢弃
		}
		cs := &cur.Steps[idx]
		cs.Attempts = st.Steps[idx].Attempts
		cs.StartedAt = st.Steps[idx].StartedAt
		cs.FinishedAt = finishedAt

		if actionErr == nil {
			cs.Status = StepResultSucceeded
			cs.LastError = ""
			succeeded := succeededNames(cur)
			if idx == len(cur.Steps)-1 {
				cur.Status = StatusCompleted
				tx.AppendEvent(EventStepSucceeded, stepEvent(def, req, step.Name, StatusCompleted, succeeded))
				tx.AppendEvent(EventExecutionCompleted, EventPayload{
					SagaName:       def.Name,
					IdempotencyKey: req.IdempotencyKey,
					Status:         StatusCompleted,
					SucceededSteps: succeeded,
				})
			} else {
				cur.Status = StatusRunning
				tx.AppendEvent(EventStepSucceeded, stepEvent(def, req, step.Name, StatusRunning, succeeded))
			}
			return nil
		}

		errMsg := actionErr.Error()
		cs.Status = StepResultFailed
		cs.LastError = errMsg
		cur.FailedStep = step.Name
		cur.FailureReason = errMsg
		cur.Status = StatusCompensating
		tx.AppendEvent(EventStepFailed, EventPayload{
			SagaName:       def.Name,
			IdempotencyKey: req.IdempotencyKey,
			Step:           step.Name,
			Status:         StatusCompensating,
			Reason:         errMsg,
			SucceededSteps: succeededNames(cur),
		})
		return nil
	})
	return err == nil, err
}

// advanceCompensation 逆序补偿下一个已确认成功的步骤。
// 返回 done=true 表示已无待补偿步骤，调用方应把执行收束为 failed 终态。
// 补偿动作返回错误时，执行在同一事务中固定为 compensation_failed 终态。
func (e *Engine) advanceCompensation(ctx context.Context, def Definition, req ExecutionRequest, st *ExecutionState) (bool, error) {
	idx := -1
	for i := len(st.Steps) - 1; i >= 0; i-- {
		if st.Steps[i].Status == StepResultSucceeded {
			idx = i
			break
		}
	}
	if idx < 0 {
		return true, nil
	}
	step := def.Steps[idx]

	var compErr error
	calledCompensation := step.Compensate != nil
	if calledCompensation {
		st.Steps[idx].CompensationAttempts++
		if err := ctx.Err(); err != nil {
			return false, err
		}
		compErr = step.Compensate(ctx, execView{state: st, payload: req.Payload})
		if err := ctx.Err(); err != nil {
			return false, err
		}
	}
	var compensatedAt time.Time
	if calledCompensation {
		compensatedAt = e.now()
	}

	err := e.store.Commit(ctx, req.BusinessKey, req.IdempotencyKey, func(tx Tx) error {
		cur := tx.State()
		if cur == nil || cur.Terminal() {
			return nil
		}
		cs := &cur.Steps[idx]
		if calledCompensation {
			cs.CompensationAttempts = st.Steps[idx].CompensationAttempts
			cs.CompensatedAt = compensatedAt
		}

		if compErr == nil {
			cs.Status = StepResultCompensated
			cs.LastError = ""
			cur.Status = StatusCompensating
			tx.AppendEvent(EventStepCompensated, EventPayload{
				SagaName:       def.Name,
				IdempotencyKey: req.IdempotencyKey,
				Step:           step.Name,
				Status:         StatusCompensating,
			})
			return nil
		}

		errMsg := compErr.Error()
		cs.Status = StepResultCompensationFailed
		cs.LastError = errMsg
		cur.FailedCompensationStep = step.Name
		cur.CompensationError = errMsg
		cur.Status = StatusCompensationFailed
		tx.AppendEvent(EventStepCompensationFailed, EventPayload{
			SagaName:       def.Name,
			IdempotencyKey: req.IdempotencyKey,
			Step:           step.Name,
			Status:         StatusCompensationFailed,
			Reason:         errMsg,
			Attempt:        cs.CompensationAttempts,
		})
		tx.AppendEvent(EventCompensationFailed, EventPayload{
			SagaName:       def.Name,
			IdempotencyKey: req.IdempotencyKey,
			Step:           step.Name,
			Status:         StatusCompensationFailed,
			Reason:         errMsg,
		})
		return nil
	})
	if err != nil {
		return false, err
	}
	return false, nil
}

// finishFailed 在补偿全部完成后把执行收束为 failed 终态并返回结果。
func (e *Engine) finishFailed(ctx context.Context, req ExecutionRequest) (Result, error) {
	err := e.store.Commit(ctx, req.BusinessKey, req.IdempotencyKey, func(tx Tx) error {
		cur := tx.State()
		if cur == nil || cur.Terminal() {
			return nil
		}
		cur.Status = StatusFailed
		tx.AppendEvent(EventExecutionFailed, EventPayload{
			SagaName:       cur.SagaName,
			IdempotencyKey: req.IdempotencyKey,
			Status:         StatusFailed,
			Step:           cur.FailedStep,
			Reason:         cur.FailureReason,
		})
		return nil
	})
	if err != nil {
		return Result{}, err
	}
	snap, err := e.store.LoadSnapshot(ctx, req.BusinessKey, req.IdempotencyKey)
	if err != nil {
		return Result{}, err
	}
	return toResult(snap.State), nil
}

func succeededNames(st *ExecutionState) []string {
	var names []string
	for _, s := range st.Steps {
		if s.Status == StepResultSucceeded {
			names = append(names, s.Name)
		}
	}
	return names
}

func stepEvent(def Definition, req ExecutionRequest, step, status string, succeeded []string) EventPayload {
	return EventPayload{
		SagaName:       def.Name,
		IdempotencyKey: req.IdempotencyKey,
		Step:           step,
		Status:         status,
		SucceededSteps: succeeded,
	}
}

func toResult(st *ExecutionState) Result {
	outcomes := make([]StepOutcome, len(st.Steps))
	for i, s := range st.Steps {
		r := s.Status
		if r == "" {
			r = StepResultPending
		}
		outcomes[i] = StepOutcome{
			Name:                 s.Name,
			Result:               r,
			Attempts:             s.Attempts,
			CompensationAttempts: s.CompensationAttempts,
			Error:                s.LastError,
			StartedAt:            s.StartedAt,
			FinishedAt:           s.FinishedAt,
		}
	}
	return Result{
		BusinessKey:            st.BusinessKey,
		SagaName:               st.SagaName,
		IdempotencyKey:         st.IdempotencyKey,
		Status:                 st.Status,
		FailureReason:          st.FailureReason,
		CompensationError:      st.CompensationError,
		FailedStep:             st.FailedStep,
		FailedCompensationStep: st.FailedCompensationStep,
		Steps:                  outcomes,
		Terminal:               st.Terminal(),
	}
}

// GetResult 查询某执行身份的当前结果，不执行任何动作。
// 未知执行身份（或 sagaName 与该执行的定义名不符）返回 ErrExecutionNotFound。
func (e *Engine) GetResult(ctx context.Context, sagaName, businessKey, idempotencyKey string) (Result, error) {
	if strings.TrimSpace(sagaName) == "" || strings.TrimSpace(businessKey) == "" || strings.TrimSpace(idempotencyKey) == "" {
		return Result{}, ErrInvalidDefinition
	}
	snap, err := e.store.LoadSnapshot(ctx, businessKey, idempotencyKey)
	if err != nil {
		return Result{}, err
	}
	if snap.State == nil || snap.State.SagaName != sagaName {
		return Result{}, ErrExecutionNotFound
	}
	return toResult(snap.State), nil
}

package txsaga

import (
	"context"
	"crypto/sha256"
	"encoding/hex"
	"errors"
	"fmt"
	"sync"
	"time"
)

// StepState 是单个步骤的持久状态。取值见 StepResult* 常量；
// 空串表示该步骤尚未被执行到（pending）。
type StepState struct {
	Name   string `json:"name"`
	Status string `json:"status"`
	// Attempts 正向动作被实际调用的次数；已确认成功后重试不会增加。
	Attempts   int       `json:"attempts"`
	LastError  string    `json:"last_error,omitempty"`
	StartedAt  time.Time `json:"started_at,omitempty"`
	FinishedAt time.Time `json:"finished_at,omitempty"`
	// CompensationAttempts 补偿动作被实际调用的次数；已确认补偿后重试不会增加。
	CompensationAttempts int       `json:"compensation_attempts,omitempty"`
	CompensatedAt        time.Time `json:"compensated_at,omitempty"`
}

// ExecutionState 是一次执行的完整持久状态，Store 的实现负责其持久化。
// 本包不规定磁盘文件格式：实现可自行选择 JSON、数据库行等任何载体。
type ExecutionState struct {
	BusinessKey            string      `json:"business_key"`
	SagaName               string      `json:"saga_name"`
	IdempotencyKey         string      `json:"idempotency_key"`
	Fingerprint            string      `json:"fingerprint"`
	Status                 string      `json:"status"`
	Steps                  []StepState `json:"steps"`
	FailureReason          string      `json:"failure_reason,omitempty"`
	FailedStep             string      `json:"failed_step,omitempty"`
	CompensationError      string      `json:"compensation_error,omitempty"`
	FailedCompensationStep string      `json:"failed_compensation_step,omitempty"`
	Payload                any         `json:"-"`
	CreatedAt              time.Time   `json:"created_at"`
	UpdatedAt              time.Time   `json:"updated_at"`
}

// Terminal 报告状态是否为固定终态。
func (s *ExecutionState) Terminal() bool {
	switch s.Status {
	case StatusCompleted, StatusFailed, StatusCompensationFailed:
		return true
	default:
		return false
	}
}

// Binding 是业务键与 Saga 定义的绑定关系。同一业务键首次执行后即绑定其定义，
// 之后以不同定义执行将得到 ErrDefinitionConflict。
type Binding struct {
	SagaName    string
	Fingerprint string
}

// Tx 是一次原子状态提交的事务视图。
//
// 引擎在 Commit 的回调中通过本接口读取既有状态、写入新状态并追加事件；
// 回调返回 nil 时，状态变更与全部事件由 Store 原子持久化，
// 回调返回错误时二者一并丢弃。基于内存的实现以互斥锁保证该原子性，
// 其它实现应使用数据库事务等同等机制。
type Tx interface {
	// Binding 返回该业务键当前绑定的 Saga 定义；未绑定时 ok 为 false。
	Binding() (b Binding, ok bool)
	// State 返回当前执行状态的可修改副本；执行尚不存在时返回 nil。
	// 对返回对象的修改仅在回调成功返回后生效。
	State() *ExecutionState
	// Create 建立执行状态（同时建立业务键与定义的绑定）。
	// 状态的 CreatedAt/UpdatedAt 由 Store 填写。
	Create(state *ExecutionState)
	// AppendEvent 追加一条 Outbox 事件。事件 ID 与发生时间由 Store 分配。
	// 事件与本次状态修改在同一事务中落盘。
	AppendEvent(eventType string, payload EventPayload)
}

// Snapshot 是某执行身份的只读快照。
type Snapshot struct {
	// State 执行状态；该身份尚无执行时为 nil。
	State *ExecutionState
	// Binding 业务键的定义绑定；未绑定时 ok 为 false。
	Binding Binding
	// Bound 是否存在绑定。
	Bound bool
}

// Store 是执行状态与 Outbox 事件的存储。
//
// 实现必须保证 Commit 的原子性：执行状态与当次追加的事件要么全部可见，
// 要么全部不可见。本包不规定落盘格式。
type Store interface {
	// LoadSnapshot 读取执行身份 (businessKey, idempotencyKey) 的状态快照，
	// 同时返回该业务键的定义绑定。
	LoadSnapshot(ctx context.Context, businessKey, idempotencyKey string) (Snapshot, error)

	// Commit 在一个原子事务中运行 fn 并提交其修改与追加的事件。
	Commit(ctx context.Context, businessKey, idempotencyKey string, fn func(tx Tx) error) error

	// ClaimPendingEvents 领取至多 max 条尚未投递（含此前发送失败被退回）
	// 的事件。每次领取即代表一次投递尝试，事件的 Deliveries 计数加一；
	// 被领取但未 Ack/Nack 的事件不会被再次领取。max<=0 表示实现自选批量。
	ClaimPendingEvents(ctx context.Context, max int) ([]*Event, error)

	// AckEvent 标记事件已投递成功，事件不再参与后续领取。
	AckEvent(ctx context.Context, eventID string) error

	// NackEvent 发送失败后退回事件：保留原事件与负载、解除领取锁定，
	// 允许继续领取。投递次数由再次领取时累计。
	NackEvent(ctx context.Context, eventID string) error
}

// ClaimLeaseStore 是在 Store 之上可选实现的带租约领取接口。
//
// 普通 ClaimPendingEvents 一旦领取即永久锁定（直到 Ack/Nack），worker 在
// Publish、Ack 或 Nack 前退出会导致事件一直滞留领取中。带租约领取则为
// 每次领取分配一个带过期时间的 ClaimID：有效期内事件不得被再次领取，
// 到期后下一次领取自动恢复，失联事件据此重新投递（至少一次语义）。
//
// 只有持有当前 ClaimID 的调用方可 Ack 或 Nack；过期领取（旧 ClaimID）的
// 操作返回 ErrStaleClaim，且不改动当前事件与新租约。
type ClaimLeaseStore interface {
	Store

	// ClaimPendingEventsLeased 领取至多 max 条可投递事件（从未领取，或
	// 此前的领取租约已到期）。每条事件获得一个新生成的 ClaimID 与从领取
	// 成功起算的 ttl 租约，事件的 Deliveries 计数加一、LastAttemptAt 更新。
	// max<=0 表示实现自选批量。
	ClaimPendingEventsLeased(ctx context.Context, ttl time.Duration, max int) ([]ClaimedEvent, error)

	// AckLeasedEvent 确认当前 claimID 对应的领取：事件被永久移除。
	// claimID 不是该事件当前有效的领取时返回 ErrStaleClaim。
	AckLeasedEvent(ctx context.Context, eventID, claimID string) error

	// NackLeasedEvent 按当前 claimID 退回事件：解除当前租约，事件立即可被
	// 再次领取（原事件字段与追加顺序保持不变）。claimID 不是该事件当前
	// 有效领取时返回 ErrStaleClaim，且不改动事件与新租约。
	NackLeasedEvent(ctx context.Context, eventID, claimID string) error
}

// ClaimedEvent 是一次带租约领取的结果。
type ClaimedEvent struct {
	// Event 被领取的事件副本（含更新后的 Deliveries/LastAttemptAt）。
	Event *Event
	// ClaimID 本次领取的唯一标识；只有持有它的调用方可 Ack/Nack。
	ClaimID string
	// ClaimedUntil 租约到期时刻；在此之前事件不会被再次领取。
	ClaimedUntil time.Time
}

// 租约相关的哨兵错误，调用方可用 errors.Is 判定。
var (
	// ErrClaimLeaseUnsupported 启用了租约但 Store 未实现 ClaimLeaseStore。
	ErrClaimLeaseUnsupported = errors.New("txsaga: store does not support claim leases")
	// ErrStaleClaim Ack/Nack 携带的 ClaimID 已不是事件当前有效的领取
	// （领取已到期、事件已被重新领取并获得新 ClaimID，或事件从未被该
	// ClaimID 领取）。出现该错误时事件与当前租约不会被改动。
	ErrStaleClaim = errors.New("txsaga: stale event claim")
)

// fingerprint 计算定义指纹：名称、版本与有序步骤名共同决定。
// 动作函数无可比较标识，调用方应通过 Name/Version 区分不同实现。
func fingerprint(d Definition) string {
	h := sha256.New()
	fmt.Fprintf(h, "name=%s\x00version=%s", d.Name, d.Version)
	for _, s := range d.Steps {
		fmt.Fprintf(h, "\x00step=%s", s.Name)
		if s.Compensate != nil {
			h.Write([]byte("\x00comp=1"))
		}
	}
	return hex.EncodeToString(h.Sum(nil))
}

// ---- 内存实现 ----

type memEvent struct {
	event Event

	// idempotencyKey 是事件所属执行的外部幂等键，与 event.BusinessKey 共同
	// 确定执行身份。历史查询按它过滤，不能从事件负载推断（负载对追加方透明）。
	idempotencyKey string

	// 普通领取（ClaimPendingEvents）的锁定标记。
	claimed bool

	// 带租约领取的状态。claimID 非空表示存在一次领取；claimedUntil 之后
	// 该领取失效，事件可被重新领取并获得新的 claimID。
	claimID      string
	claimedUntil time.Time
}

type memTx struct {
	s        *MemoryStore
	business string
	idem     string
	binding  *Binding
	state    *ExecutionState
	created  bool
	staged   []Event
}

func (t *memTx) Binding() (Binding, bool) {
	if t.binding != nil {
		return *t.binding, true
	}
	return Binding{}, false
}

func (t *memTx) State() *ExecutionState { return t.state }

func (t *memTx) Create(state *ExecutionState) {
	state.BusinessKey = t.business
	state.IdempotencyKey = t.idem
	t.state = state
	t.created = true
}

func (t *memTx) AppendEvent(eventType string, p EventPayload) {
	t.staged = append(t.staged, Event{
		BusinessKey: t.business,
		Type:        eventType,
		Payload:     p,
	})
}

// MemoryStore 是进程内的 Store 实现，仅依赖标准库，适用于嵌入与测试。
// 不向磁盘写入任何文件；进程退出后状态不保留。
type MemoryStore struct {
	mu       sync.Mutex
	execs    map[string]*ExecutionState
	bindings map[string]Binding
	events   map[string]*memEvent
	pending  []string // 未领取事件 ID，保持追加顺序
	// history 是只增的审计链：按追加顺序保存每条事件的指针，与 events 中
	// 的活动对象共享同一 memEvent，因此领取/退回/重投更新投递元数据后，
	// 历史读到的是最新计数；Ack 只从 events/pending 移除活动副本，审计副本
	// 在此永久保留。顺序仅由追加位置决定，不受领取、退回、租约影响。
	history  []*memEvent
	seq      uint64
	claimSeq uint64 // 租约 ClaimID 序列
	now      func() time.Time
}

// 编译期断言：MemoryStore 同时满足 Store、ClaimLeaseStore 与 EventHistoryStore。
var (
	_ Store             = (*MemoryStore)(nil)
	_ ClaimLeaseStore   = (*MemoryStore)(nil)
	_ EventHistoryStore = (*MemoryStore)(nil)
)

// NewMemoryStore 创建内存状态存储。
func NewMemoryStore() *MemoryStore {
	return &MemoryStore{
		execs:    make(map[string]*ExecutionState),
		bindings: make(map[string]Binding),
		events:   make(map[string]*memEvent),
		now:      time.Now,
	}
}

func execID(businessKey, idempotencyKey string) string {
	return businessKey + "\x00" + idempotencyKey
}

func cloneState(s *ExecutionState) *ExecutionState {
	if s == nil {
		return nil
	}
	c := *s
	if s.Steps != nil {
		c.Steps = append([]StepState(nil), s.Steps...)
	}
	return &c
}

// LoadSnapshot 实现 Store 接口。
func (s *MemoryStore) LoadSnapshot(_ context.Context, businessKey, idempotencyKey string) (Snapshot, error) {
	s.mu.Lock()
	defer s.mu.Unlock()

	snap := Snapshot{}
	if b, ok := s.bindings[businessKey]; ok {
		snap.Binding, snap.Bound = b, true
	}
	if st, ok := s.execs[execID(businessKey, idempotencyKey)]; ok {
		snap.State = cloneState(st)
	}
	return snap, nil
}

// Commit 实现 Store 接口：整库加锁，状态与事件原子可见。
func (s *MemoryStore) Commit(_ context.Context, businessKey, idempotencyKey string, fn func(Tx) error) error {
	s.mu.Lock()
	defer s.mu.Unlock()

	t := &memTx{s: s, business: businessKey, idem: idempotencyKey}
	if b, ok := s.bindings[businessKey]; ok {
		bc := b
		t.binding = &bc
	}
	if st, ok := s.execs[execID(businessKey, idempotencyKey)]; ok {
		t.state = cloneState(st)
	}

	if err := fn(t); err != nil {
		return err // 回调失败： staged 事件与状态副本一并丢弃
	}

	now := s.now()
	if t.state != nil {
		if t.created {
			if _, exists := s.execs[execID(businessKey, idempotencyKey)]; exists {
				return errors.New("txsaga: execution already exists")
			}
			t.state.CreatedAt = now
			// 首次执行建立业务键与定义的绑定；同键的后续执行定义一致，覆盖无害。
			if _, ok := s.bindings[businessKey]; !ok {
				s.bindings[businessKey] = Binding{SagaName: t.state.SagaName, Fingerprint: t.state.Fingerprint}
			}
		}
		t.state.UpdatedAt = now
		s.execs[execID(businessKey, idempotencyKey)] = cloneState(t.state)
	}

	for i := range t.staged {
		ev := t.staged[i]
		s.seq++
		ev.ID = fmt.Sprintf("evt-%020d", s.seq)
		ev.OccurredAt = now
		me := &memEvent{event: ev, idempotencyKey: idempotencyKey}
		s.events[ev.ID] = me
		s.pending = append(s.pending, ev.ID)
		// 与状态、活动事件在同一临界区内追加，保证历史读取只见原子提交的事件；
		// 与 s.events 共享同一指针，投递元数据始终为最新值，Ack 后仍可审计。
		s.history = append(s.history, me)
	}
	return nil
}

// ClaimPendingEvents 实现 Store 接口。
func (s *MemoryStore) ClaimPendingEvents(_ context.Context, max int) ([]*Event, error) {
	s.mu.Lock()
	defer s.mu.Unlock()

	if max <= 0 {
		max = 16
	}
	now := s.now()
	out := make([]*Event, 0, max)
	remaining := s.pending[:0]
	for _, id := range s.pending {
		me := s.events[id]
		if me == nil {
			continue // 已 Ack 移除，丢弃墓碑 ID
		}
		// 已被带租约领取且租约仍有效的事件不得被无租约领取再次取得。
		if me.claimID != "" && now.Before(me.claimedUntil) {
			remaining = append(remaining, id)
			continue
		}
		if len(out) >= max {
			remaining = append(remaining, id)
			continue
		}
		me.claimed = true
		// 接管已到期的租约事件时清除旧租约，避免遗留失效的 ClaimID。
		me.claimID = ""
		me.claimedUntil = time.Time{}
		me.event.deliveries++
		me.event.lastAttemptAt = now
		cp := me.event
		out = append(out, &cp)
	}
	s.pending = remaining
	return out, nil
}

// ClaimPendingEventsLeased 实现 ClaimLeaseStore 接口。
// 从未领取或当前租约已到期的事件可被领取；每次领取生成新的 ClaimID。
// 租约内事件留在追加队列中原位跳过，因此到期恢复与 Nack 退回都不改变
// 事件间的追加顺序；已 Ack 的事件 ID 作为墓碑在扫描时清除。
func (s *MemoryStore) ClaimPendingEventsLeased(_ context.Context, ttl time.Duration, max int) ([]ClaimedEvent, error) {
	s.mu.Lock()
	defer s.mu.Unlock()

	if max <= 0 {
		max = 16
	}
	now := s.now()
	out := make([]ClaimedEvent, 0, max)
	live := s.pending[:0]
	for _, id := range s.pending {
		me := s.events[id]
		if me == nil {
			continue // 已 Ack 移除，丢弃墓碑 ID
		}
		if me.claimID != "" && now.Before(me.claimedUntil) {
			live = append(live, id) // 有效租约内：原位保留，本次跳过
			continue
		}
		if len(out) >= max {
			live = append(live, id) // 批量已满：保留顺序，下轮再领
			continue
		}
		s.claimSeq++
		cid := fmt.Sprintf("claim-%020d", s.claimSeq)
		me.claimID = cid
		me.claimedUntil = now.Add(ttl)
		me.event.deliveries++
		me.event.lastAttemptAt = now
		cp := me.event
		out = append(out, ClaimedEvent{
			Event:        &cp,
			ClaimID:      cid,
			ClaimedUntil: me.claimedUntil,
		})
		live = append(live, id) // 租约期内留在队列，到期后原位可恢复
	}
	s.pending = live
	return out, nil
}

// AckEvent 实现 Store 接口。
func (s *MemoryStore) AckEvent(_ context.Context, eventID string) error {
	s.mu.Lock()
	defer s.mu.Unlock()
	if _, ok := s.events[eventID]; !ok {
		return fmt.Errorf("txsaga: event %q not found", eventID)
	}
	delete(s.events, eventID)
	return nil
}

// AckLeasedEvent 实现 ClaimLeaseStore 接口：仅当前 claimID 可确认。
func (s *MemoryStore) AckLeasedEvent(_ context.Context, eventID, claimID string) error {
	s.mu.Lock()
	defer s.mu.Unlock()
	me, ok := s.events[eventID]
	if !ok {
		return fmt.Errorf("txsaga: event %q not found", eventID)
	}
	if me.claimID != claimID {
		// 含从未租约领取、旧 ClaimID 已到期、已被新领取取代三种情形，
		// 均不得改动当前事件或新租约。
		return fmt.Errorf("txsaga: event %q claim %q is not current: %w", eventID, claimID, ErrStaleClaim)
	}
	delete(s.events, eventID)
	return nil
}

// NackEvent 实现 Store 接口。
func (s *MemoryStore) NackEvent(_ context.Context, eventID string) error {
	s.mu.Lock()
	defer s.mu.Unlock()
	me, ok := s.events[eventID]
	if !ok {
		return fmt.Errorf("txsaga: event %q not found", eventID)
	}
	if !me.claimed {
		return nil // 幂等退回：未在领取中的事件无需处理
	}
	me.claimed = false
	s.pending = append(s.pending, eventID)
	return nil
}

// NackLeasedEvent 实现 ClaimLeaseStore 接口：仅当前 claimID 可退回，
// 退回后租约解除、事件立即可领取，且保持原追加顺序。
func (s *MemoryStore) NackLeasedEvent(_ context.Context, eventID, claimID string) error {
	s.mu.Lock()
	defer s.mu.Unlock()
	me, ok := s.events[eventID]
	if !ok {
		return fmt.Errorf("txsaga: event %q not found", eventID)
	}
	if me.claimID != claimID {
		return fmt.Errorf("txsaga: event %q claim %q is not current: %w", eventID, claimID, ErrStaleClaim)
	}
	// 租约事件始终留在追加队列中，退回只解除租约：事件立即可领取，
	// 且相对其它事件的顺序不变。
	me.claimID = ""
	me.claimedUntil = time.Time{}
	return nil
}

// PendingCount 返回当前立即可领取的事件数（不含有效租约内的事件），
// 便于观测与测试。
func (s *MemoryStore) PendingCount() int {
	s.mu.Lock()
	defer s.mu.Unlock()
	now := s.now()
	n := 0
	for _, id := range s.pending {
		me := s.events[id]
		if me == nil {
			continue
		}
		if me.claimID != "" && now.Before(me.claimedUntil) {
			continue
		}
		n++
	}
	return n
}

// TotalEvents 返回存储中全部事件数（含领取中、待投递）。
func (s *MemoryStore) TotalEvents() int {
	s.mu.Lock()
	defer s.mu.Unlock()
	return len(s.events)
}

// ListEvents 实现 EventHistoryStore 接口：在同一把锁内扫描只增审计链，
// 因此每页只可能读到整次 Commit 已提交的事件，且与并发执行、补偿、投递
// 互不干扰。查询本身不修改任何字段。
func (s *MemoryStore) ListEvents(_ context.Context, q EventHistoryQuery) (EventHistoryPage, error) {
	limit := q.Limit
	if limit <= 0 {
		limit = defaultEventHistoryLimit
	}

	s.mu.Lock()
	defer s.mu.Unlock()

	// 先校验执行身份与 Saga 名称：不存在（含仅有事件、没有执行记录的情形）
	// 或名称不符一律 ErrExecutionNotFound。
	st, ok := s.execs[execID(q.BusinessKey, q.IdempotencyKey)]
	if !ok || st.SagaName != q.SagaName {
		return EventHistoryPage{}, ErrExecutionNotFound
	}

	start := 0
	if q.AfterID != "" {
		idx := -1
		for i, me := range s.history {
			if me.event.ID == q.AfterID &&
				me.event.BusinessKey == q.BusinessKey &&
				me.idempotencyKey == q.IdempotencyKey {
				idx = i
				break
			}
		}
		// 游标不存在或属于其它执行：不返回部分结果，也不触碰任何状态。
		if idx < 0 {
			return EventHistoryPage{}, ErrEventCursorNotFound
		}
		start = idx + 1
	}

	page := EventHistoryPage{Events: []EventRecord{}}
	if len(page.Events) == 0 && q.AfterID != "" {
		// 空页（游标已是最后一条）时回传入参游标，重复查询保持幂等，
		// 不会因空游标而误回到链首。
		page.NextAfterID = q.AfterID
	}
	next := start // 本页之后第一个待检查的审计链位置
	for i := start; i < len(s.history) && len(page.Events) < limit; i++ {
		me := s.history[i]
		if me.event.BusinessKey != q.BusinessKey || me.idempotencyKey != q.IdempotencyKey {
			continue
		}
		page.Events = append(page.Events, toEventRecord(me))
		next = i + 1
	}
	if len(page.Events) > 0 {
		page.NextAfterID = page.Events[len(page.Events)-1].ID
	}
	for i := next; i < len(s.history); i++ {
		me := s.history[i]
		if me.event.BusinessKey == q.BusinessKey && me.idempotencyKey == q.IdempotencyKey {
			page.HasMore = true
			break
		}
	}
	return page, nil
}

// toEventRecord 把内部事件复制为脱离存储的只读记录；与活动 Outbox 事件
// 共享同一追加时刻的身份字段，投递元数据取读取当下的最新值。
func toEventRecord(me *memEvent) EventRecord {
	return EventRecord{
		ID:            me.event.ID,
		Type:          me.event.Type,
		OccurredAt:    me.event.OccurredAt,
		Payload:       cloneEventPayload(me.event.Payload),
		BusinessKey:   me.event.BusinessKey,
		Deliveries:    me.event.deliveries,
		LastAttemptAt: me.event.lastAttemptAt,
	}
}

// cloneEventPayload 复制负载中可变的切片，避免调用方修改记录影响存储内部。
func cloneEventPayload(p any) any {
	if ep, ok := p.(EventPayload); ok {
		if ep.SucceededSteps != nil {
			ep.SucceededSteps = append([]string(nil), ep.SucceededSteps...)
		}
		return ep
	}
	return p
}

