package txsaga

import (
	"context"
	"errors"
	"time"
)

// Publisher 由调用方实现，负责把一条 Outbox 事件发送到实际的下游
// （消息代理、HTTP 回调、其它进程内通道等）。本包不提供任何具体中间件适配。
//
// 实现应当满足至少一次投递语义：返回 error 时事件会被保留并可再次领取，
// 因此下游消费侧需要自身幂等。返回 nil 即视为投递成功，事件被标记已投递。
type Publisher interface {
	// Publish 发送单个事件。event.Payload 为结构化负载，可用 encoding/json 序列化。
	Publish(ctx context.Context, event Event) error
}

// PublisherFunc 让普通函数满足 Publisher 接口。
type PublisherFunc func(ctx context.Context, event Event) error

// Publish 实现 Publisher 接口。
func (f PublisherFunc) Publish(ctx context.Context, event Event) error { return f(ctx, event) }

// Relay 在 Store 与 Publisher 之间搬运 Outbox 事件：
// 领取待投递事件、交给 Publisher、成功 Ack、失败 Nack 后保留并允许重试。
// Relay 可被多个 worker 并发使用；零值不可用，请用 NewRelay 创建。
type Relay struct {
	store     Store
	publisher Publisher
	// batch 单次领取上限。
	batch int
	// retryBackoff 一批事件全部发送失败后的再次领取间隔。
	retryBackoff time.Duration
	// idleWait 没有待投递事件时的轮询等待。
	idleWait time.Duration
	// leaseTTL > 0 时启用带租约领取：worker 在 Publish/Ack/Nack 前退出，
	// 事件在租约到期后的下一轮自动恢复；0 表示沿用普通领取的默认行为。
	leaseTTL time.Duration
	// now 等时间依赖直接使用 time 包标准行为。
	sleep func(ctx context.Context, d time.Duration) error
}

// RelayOption 配置 Relay。
type RelayOption func(*Relay)

// WithBatch 设置单次领取事件数，默认 16。
func WithBatch(n int) RelayOption {
	return func(r *Relay) {
		if n > 0 {
			r.batch = n
		}
	}
}

// WithRetryBackoff 设置发送失败后的重试间隔，默认 200ms。
func WithRetryBackoff(d time.Duration) RelayOption {
	return func(r *Relay) {
		if d > 0 {
			r.retryBackoff = d
		}
	}
}

// WithIdleWait 设置无事件时的轮询间隔，默认 500ms。
func WithIdleWait(d time.Duration) RelayOption {
	return func(r *Relay) {
		if d > 0 {
			r.idleWait = d
		}
	}
}

// WithClaimLease 启用带租约领取并设置租约时长。
//
// 仅正时长生效；传入 0 或负时长不启用租约，Relay 沿用普通 ClaimPendingEvents
// 的默认行为。启用后，每次领取的事件在 ttl 内不会被再次领取；worker 在
// Publish、Ack 或 Nack 前退出时，事件于租约到期后的下一次 DeliverOnce/Run
// 自动恢复重投，从而保证至少一次投递。Store 必须实现 ClaimLeaseStore，
// 否则 DeliverOnce 返回 ErrClaimLeaseUnsupported（可 errors.Is）。
func WithClaimLease(ttl time.Duration) RelayOption {
	return func(r *Relay) {
		if ttl > 0 {
			r.leaseTTL = ttl
		}
	}
}

// NewRelay 创建事件投递器。
func NewRelay(store Store, publisher Publisher, opts ...RelayOption) *Relay {
	r := &Relay{
		store:        store,
		publisher:    publisher,
		batch:        16,
		retryBackoff: 200 * time.Millisecond,
		idleWait:     500 * time.Millisecond,
	}
	r.sleep = sleepWithContext
	for _, opt := range opts {
		opt(r)
	}
	return r
}

func sleepWithContext(ctx context.Context, d time.Duration) error {
	t := time.NewTimer(d)
	defer t.Stop()
	select {
	case <-ctx.Done():
		return ctx.Err()
	case <-t.C:
		return nil
	}
}

// RelayResult 是单轮投递的结果统计。
type RelayResult struct {
	// Claimed 本轮领取的事件数。
	Claimed int
	// Delivered 发送成功并 Ack 的事件数。
	Delivered int
	// Failed 发送失败并 Nack 保留的事件数。
	Failed int
}

// DeliverOnce 执行一轮领取与投递，不阻塞等待。没有事件时立即返回空结果。
// 单个事件发送失败不影响同批其它事件；失败事件被 Nack，可在后续轮次继续领取。
//
// 通过 WithClaimLease 启用租约且 Store 未实现 ClaimLeaseStore 时，
// 返回包装了 ErrClaimLeaseUnsupported 的错误（可 errors.Is 判定）。
func (r *Relay) DeliverOnce(ctx context.Context) (RelayResult, error) {
	if r.leaseTTL > 0 {
		leased, ok := r.store.(ClaimLeaseStore)
		if !ok {
			return RelayResult{}, ErrClaimLeaseUnsupported
		}
		return r.deliverOnceLeased(ctx, leased)
	}
	return r.deliverOnce(ctx)
}

// deliverOnce 是未启用租约时的默认路径：领取即锁定，失败立即退回。
func (r *Relay) deliverOnce(ctx context.Context) (RelayResult, error) {
	events, err := r.store.ClaimPendingEvents(ctx, r.batch)
	if err != nil {
		return RelayResult{}, err
	}
	res := RelayResult{Claimed: len(events)}
	for _, ev := range events {
		if err := ctx.Err(); err != nil {
			// 退出前把尚未处理的已领取事件退回，避免它们滞留到进程重启。
			_ = r.store.NackEvent(ctx, ev.ID)
			res.Failed++
			continue
		}
		if err := r.publisher.Publish(ctx, *ev); err != nil {
			if nackErr := r.store.NackEvent(ctx, ev.ID); nackErr != nil {
				return res, nackErr
			}
			res.Failed++
			continue
		}
		if err := r.store.AckEvent(ctx, ev.ID); err != nil {
			return res, err
		}
		res.Delivered++
	}
	return res, nil
}

// deliverOnceLeased 是启用租约后的投递路径。
//
// 取消语义：
//   - 领取后、Publish 前 ctx 已取消：事件从未交给 Publish，按当前 ClaimID
//     立即 Nack，等不到租约到期；
//   - Publish 进行中取消：按 Publish 的返回结果处理，nil 走 Ack，error 走
//     Nack，不因 ctx 取消改变结论；
//   - worker 在任何一步退出（未 Nack）：租约到期后事件自动恢复重投。
//
// Ack/Nack 使用独立上下文，避免调用方 ctx 已取消导致确认/退回被 Store
// 拒绝而被迫等待租约到期。旧 ClaimID（租约已到期、事件被他人重新领取）
// 返回 ErrStaleClaim 时不作任何操作：当前事件与新租约由接管方负责。
func (r *Relay) deliverOnceLeased(ctx context.Context, store ClaimLeaseStore) (RelayResult, error) {
	claims, err := store.ClaimPendingEventsLeased(ctx, r.leaseTTL, r.batch)
	if err != nil {
		return RelayResult{}, err
	}
	res := RelayResult{Claimed: len(claims)}
	for _, c := range claims {
		if err := ctx.Err(); err != nil {
			if nackErr := store.NackLeasedEvent(context.Background(), c.Event.ID, c.ClaimID); nackErr != nil &&
				!errors.Is(nackErr, ErrStaleClaim) {
				return res, nackErr
			}
			res.Failed++
			continue
		}
		pubErr := r.publisher.Publish(ctx, *c.Event)
		if pubErr != nil {
			if nackErr := store.NackLeasedEvent(context.Background(), c.Event.ID, c.ClaimID); nackErr != nil &&
				!errors.Is(nackErr, ErrStaleClaim) {
				return res, nackErr
			}
			res.Failed++
			continue
		}
		if ackErr := store.AckLeasedEvent(context.Background(), c.Event.ID, c.ClaimID); ackErr != nil &&
			!errors.Is(ackErr, ErrStaleClaim) {
			return res, ackErr
		}
		res.Delivered++
	}
	return res, nil
}

// Run 循环执行投递，直到 ctx 被取消。至少一轮成功投递后返回 ctx.Err()。
// 全部事件发送失败的批次后按重试间隔等待；无事件时按空闲间隔等待。
func (r *Relay) Run(ctx context.Context) error {
	for {
		if err := ctx.Err(); err != nil {
			return err
		}
		res, err := r.DeliverOnce(ctx)
		if err != nil {
			return err
		}
		var wait time.Duration
		switch {
		case res.Claimed == 0:
			wait = r.idleWait
		case res.Failed > 0 && res.Delivered == 0:
			wait = r.retryBackoff
		default:
			wait = 0 // 本轮有成功投递，立即继续领取，尽快排空积压
		}
		if wait > 0 {
			if err := r.sleep(ctx, wait); err != nil {
				return err
			}
		}
	}
}

package txsaga

import (
	"context"
	"errors"
	"strings"
	"time"
)

// 事件历史查询相关的哨兵错误，调用方可用 errors.Is 判定。
var (
	// ErrEventHistoryUnsupported 当前 Store 未实现 EventHistoryStore。
	// 既有自定义 Store 无需新增任何方法即可继续使用，只是不支持历史查询。
	ErrEventHistoryUnsupported = errors.New("txsaga: store does not support event history")
	// ErrEventCursorNotFound 分页游标 AfterID 未命中：事件不存在，或不属于
	// 本次查询给定的执行身份。返回该错误时不返回任何记录，也不改变任何状态。
	ErrEventCursorNotFound = errors.New("txsaga: event cursor not found")
)

// defaultEventHistoryLimit 是单页上限非正数时采用的默认页大小。
const defaultEventHistoryLimit = 100

// EventHistoryQuery 是一次只读执行事件历史查询的输入。
//
// 执行身份由 Saga 名称、业务键与外部幂等键共同确定，与 Execute/GetResult
// 保持同一口径。事件严格按发生（追加）顺序分页，Ack、Nack、租约到期与
// 投递次数增加都不会改变顺序。
type EventHistoryQuery struct {
	// SagaName Saga 定义名称，必填；与执行记录的名称不符时返回 ErrExecutionNotFound。
	SagaName string
	// BusinessKey 业务键，必填。
	BusinessKey string
	// IdempotencyKey 外部幂等键，必填。
	IdempotencyKey string
	// AfterID 上一页最后一条事件 ID；为空表示从头查询。
	// 命中后从该事件的下一条开始返回；不属于本执行时返回 ErrEventCursorNotFound。
	AfterID string
	// Limit 单页事件数上限；非正数时按 100 条返回。
	Limit int
}

// EventRecord 是执行事件链中的一条只读审计记录。
//
// 身份、类型、发生时间与结构化负载在追加时确定；投递元数据
// （Deliveries/LastAttemptAt）反映查询当下的最新值。已 Ack 的事件同样
// 保留一份不可变身份字段、可继续审计的副本。记录为快照值，与存储内部
// 结构脱离，调用方修改不影响后续领取、投递与再次查询。
type EventRecord struct {
	// ID 事件唯一 ID，由存储在追加时分配，追加顺序单调。
	ID string
	// Type 事件类型，取值为 Event* 常量。
	Type string
	// OccurredAt 事件发生时间（状态提交时刻）。
	OccurredAt time.Time
	// Payload 结构化负载，即追加时的 EventPayload，可用 encoding/json 序列化。
	Payload any
	// BusinessKey 业务键。
	BusinessKey string
	// Deliveries 截至查询时该事件已进入领取/投递流程的次数（含首次）。
	// 发送失败退回后再次领取会增大；Ack 后保留最后一次计数。
	Deliveries int
	// LastAttemptAt 最近一次领取时间；从未被领取为零值。
	LastAttemptAt time.Time
}

// EventHistoryPage 是一页按追加顺序排列的执行事件。
type EventHistoryPage struct {
	// Events 本页事件，按事件发生及追加顺序升序排列。
	Events []EventRecord
	// NextAfterID 下一页查询应使用的游标：本页最后一条事件 ID。
	// 本页为空时与入参 AfterID 语义一致（从头查询则为空）。
	NextAfterID string
	// HasMore 游标之后是否还有事件。
	HasMore bool
}

// EventHistoryStore 是在 Store 之上可选实现的只读执行事件历史接口。
//
// 持久化 Store 通过实现本接口提供与 MemoryStore 一致的历史结果：
// 查询必须只读（不得推进执行、调用动作、追加事件或改变 Outbox 领取/投递
// 状态），并且每页只读取原子提交后可见的事件——一次 Commit 追加的多条
// 事件要么整体可见、要么整体不可见，跨页顺序始终等于追加顺序。
type EventHistoryStore interface {
	Store

	// ListEvents 按追加顺序返回一次执行的一页事件。
	//
	// 查询语义：
	//   - 执行不存在（或事件链为空但无执行记录）返回 ErrExecutionNotFound；
	//   - sagaName 与执行绑定的 Saga 名称不符返回 ErrExecutionNotFound；
	//   - afterID 非空且未命中（事件不存在或属于其它执行）返回 ErrEventCursorNotFound；
	//   - limit<=0 时按 100 条返回。
	//
	// 出错时不得返回部分结果，也不得改变任何状态与投递元数据。
	// 返回的记录须包含待投递、领取中、发送失败退回以及已 Ack 的全部事件，
	// 已 Ack 事件保留可审计副本。
	ListEvents(ctx context.Context, q EventHistoryQuery) (EventHistoryPage, error)
}

// ListEvents 按执行身份只读回看本次执行的完整事件链中的一页。
//
// 执行身份为 Saga 名称、业务键与外部幂等键，与 GetResult 同口径：
//   - 缺少 Saga 名称、业务键或外部幂等键：ErrInvalidDefinition；
//   - 执行不存在或 Saga 名称不匹配：ErrExecutionNotFound；
//   - AfterID 不属于该执行：ErrEventCursorNotFound；
//   - Store 未实现 EventHistoryStore：ErrEventHistoryUnsupported。
//
// 查询不推进执行、不调用动作、不追加事件，也不改变 Outbox 的领取、退回、
// 投递计数或 Ack 状态；事件顺序固定为追加顺序，分页通过
// EventHistoryPage.NextAfterID 继续，HasMore 报告游标之后是否还有事件。
func (e *Engine) ListEvents(ctx context.Context, q EventHistoryQuery) (EventHistoryPage, error) {
	if strings.TrimSpace(q.SagaName) == "" ||
		strings.TrimSpace(q.BusinessKey) == "" ||
		strings.TrimSpace(q.IdempotencyKey) == "" {
		return EventHistoryPage{}, ErrInvalidDefinition
	}
	if q.Limit <= 0 {
		q.Limit = defaultEventHistoryLimit
	}
	hs, ok := e.store.(EventHistoryStore)
	if !ok {
		return EventHistoryPage{}, ErrEventHistoryUnsupported
	}
	return hs.ListEvents(ctx, q)
}

