	// 自增。未确认结果的步骤被重新调用（含本次调用内的重试与跨调用续跑）
	// 时该值增大，调用方据此判断是否发生重复处理。
	startedAt := e.now()
	var actionErr error
	calls := 0
	for {
		if err := ctx.Err(); err != nil {
			return false, err
		}
		st.Steps[idx].Attempts++
		calls++
		actionErr = step.Action(ctx, execView{state: st, payload: req.Payload})
